def __repr__(self):
    # TODO: add generic function to format text nicely in a repr (see EventNoteRevision.__repr__)
    desc = self.description.replace('\n', ' ')
    if len(desc) > 50:
        desc = desc[:50] + '...'
    return '<SurveyText({}, {}): "{}")>'.format(self.id, self.survey_id, desc)

